public class Solution {
    public int missingNumber(int[] nums) {
        boolean[] seen = new boolean[nums.length];  // должно быть length+1
        for (int x : nums) seen[x] = true;  // OOB при x == nums.length
        for (int i = 0; i < seen.length; i++) if (!seen[i]) return i;
        return -1;
    }
}
